// App Router async server component for request-time data fetching
export default async function UserDashboard() {
  // Fetch user-specific data that changes on each request
  // No 'use cache' directive - this data is dynamic per request
  const res = await fetch('http://localhost:3000/api/user/preferences', {
    cache: 'no-store', // Ensures fresh data on each request
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <pre>{JSON.stringify(preferences, null, 2)}</pre>
    </div>
  );
}

